(function(root){'use strict';
function has(v){return v!==undefined&&v!==null&&String(v).trim()!=='';}
function date(s){if(!/^\d{4}-\d{2}-\d{2}$/.test(s||''))return false;const d=new Date(s+'T00:00:00Z');return Number.isFinite(+d)&&d.toISOString().slice(0,10)===s;}
function validate(v){if(has(v.atmpRate)){const value=String(v.atmpRate).trim().replace(',','.');if(!/^\d+(\.\d{1,4})?$/.test(value)||Number(value)>100)throw Error('Le taux AT/MP doit être compris entre 0 et 100 %, avec au plus 4 décimales.');v.atmpRate=value;}for(const k of ['atmpValidFrom','atmpValidUntil'])if(has(v[k])&&!date(v[k]))throw Error('Date de validité AT/MP invalide.');if(v.atmpValidFrom&&v.atmpValidUntil&&v.atmpValidUntil<v.atmpValidFrom)throw Error('La fin de validité AT/MP précède la date d’effet.');if(has(v.atmpRiskCode)&&String(v.atmpRiskCode).trim().length>20)throw Error('Code risque AT/MP trop long.');if(has(v.atmpRiskCode))v.atmpRiskCode=String(v.atmpRiskCode).trim();return v;}
function description(c){if(!has(c.atmpRiskCode)&&!has(c.atmpRate))return '';const rate=has(c.atmpRate)?Number(String(c.atmpRate).replace(',','.')).toLocaleString('fr-FR',{maximumFractionDigits:4})+' %':'à renseigner';return 'AT/MP · Code risque : '+(c.atmpRiskCode||'à renseigner')+' · Taux notifié : '+rate+(c.atmpValidFrom?' · Effet : '+c.atmpValidFrom.split('-').reverse().join('/'):'');}
function contribution(c,period){validate({...c});if(!has(c.atmpRiskCode)||!has(c.atmpRate)||!date(c.atmpValidFrom))throw Error('Complétez le code risque, le taux et la date d’effet AT/MP dans la fiche entreprise.');if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(period||''))throw Error('Période de paie invalide.');const first=period+'-01',[y,m]=period.split('-').map(Number),last=new Date(Date.UTC(y,m,0)).toISOString().slice(0,10);if(c.atmpValidFrom>first||(c.atmpValidUntil&&c.atmpValidUntil<last))throw Error('Le taux AT/MP ne couvre pas tout ce mois. Vérifiez la notification et les éventuels changements de taux.');return{label:'Accidents du travail et maladies professionnelles · '+c.atmpRiskCode,baseMode:'gross',base:'0',employeeRate:'0',employerRate:String(c.atmpRate).replace(',','.'),csgInclude:'Non',atmpRiskCode:c.atmpRiskCode,atmpReference:c.atmpReference||''};}
const api={validate,description,contribution};if(typeof module!=='undefined'&&module.exports)module.exports=api;root.CompanyAtmp=api;
})(typeof globalThis!=='undefined'?globalThis:this);
